INSERT INTO `node_revisions` VALUES
    (3,3,1,'Arsenal''s return to the summit','<p><img src="/showcase-images/arsenal-champs-2026.jpg" alt="Arsenal players celebrating with the Premier League trophy" width="1200" height="675" style="display:block;max-width:100%;height:auto;margin-bottom:1.5em"></p>Arsenal won the 2025/2026 Premier League and ended a 22-year wait for the championship. Years of investment in young players, recruitment, and a clear identity produced a team capable of sustaining a challenge.\r\n\r\nThe side combined disciplined possession with aggressive pressing and a defence built to control matches. Leaders guided a core that had developed together, while competition for places ensured injuries did not derail the campaign.\r\n\r\nThe title reflected the bond between team and supporters. Arsenal returned to the summit through planning, tactical evolution, and faith in a group that turned promise into achievement.','<img class="showcase-teaser-image" src="/showcase-images/arsenal-champs-2026.jpg" alt="Arsenal players celebrating with the Premier League trophy" width="240" height="135" style="position:absolute;left:0;top:0;display:block;width:240px;height:135px;margin:0;object-fit:cover">Arsenal won the 2025/2026 Premier League and ended a 22-year wait through patient rebuilding, tactical clarity, and a squad ready for a title race.','',UNIX_TIMESTAMP(),1),
    (4,4,1,'The global rise of Nollywood','<p><img src="/showcase-images/nollywood.jpg" alt="Nollywood sign and Nigerian flag on a sunlit hillside" width="1200" height="675" style="display:block;max-width:100%;height:auto;margin-bottom:1.5em"></p>Nollywood has grown from a resourceful home-video industry into one of the world’s most energetic centres of film and television. Early filmmakers worked with limited budgets and direct distribution, yet created stories audiences recognised immediately.\r\n\r\nFilms circulated across Africa and the diaspora, giving viewers characters, languages, and settings often absent from imported entertainment. The industry created opportunities for actors, writers, technicians, designers, musicians, and entrepreneurs.\r\n\r\nDigital production and streaming expanded Nollywood’s reach. Larger budgets and international partnerships now sit alongside its independent sector. Local stories continue to travel far beyond Nigeria.','<img class="showcase-teaser-image" src="/showcase-images/nollywood.jpg" alt="Nollywood sign and Nigerian flag on a sunlit hillside" width="240" height="135" style="position:absolute;left:0;top:0;display:block;width:240px;height:135px;margin:0;object-fit:cover">Nollywood has grown from a resourceful home-video industry into one of the world’s most energetic centres of film and television.','',UNIX_TIMESTAMP(),1),
    (5,5,1,'Poland''s transformation into a European leader','<p><img src="/showcase-images/poland-warsaw.jpg" alt="Warsaw Old Town and Castle Square in Poland" width="1200" height="675" style="display:block;max-width:100%;height:auto;margin-bottom:1.5em"></p>Since the fall of communism, Poland has undergone one of Europe’s most significant transformations. The transition from central planning released entrepreneurial energy and connected businesses with international markets.\r\n\r\nEuropean Union membership accelerated the process. Investment in transport, cities, universities, and digital infrastructure improved connections, while Polish companies became important parts of European supply chains.\r\n\r\nPoland’s population, strategic location, and commitment to regional security increased its influence. Challenges remain, but Poland has emerged as a resilient economy and a leading state whose choices will help define Europe’s future.','<img class="showcase-teaser-image" src="/showcase-images/poland-warsaw.jpg" alt="Warsaw Old Town and Castle Square in Poland" width="240" height="135" style="position:absolute;left:0;top:0;display:block;width:240px;height:135px;margin:0;object-fit:cover">Since the fall of communism, Poland has transformed its economy and become an increasingly influential member of the European Union.','',UNIX_TIMESTAMP(),1);
